using System.Text.RegularExpressions;
using Blocwerk.Client.Pages;
using Blocwerk.Web.Components.OfflineClient;
using static Blocwerk.Core.Tests.OfflineClientStore.StoreWorld;
using static Blocwerk.Core.Tests.OfflineClientViews.ViewWorld;

namespace Blocwerk.Core.Tests.OfflineClientViews;

/// <summary>
/// The client styles its views with stylesheets of its own (client-base and client-components, the Server pages' rules
/// its markup uses, generated by build/subset-client-css.mjs): it loads no Web stylesheet, so a Server CSS edit is no new
/// client version; and every class its views render is styled by one of its stylesheets, unless it is one the Server
/// pages style only with an interop the client does not have.
/// </summary>
public sealed partial class ClientStylesheetTests
{
    // Classes the views render that the client leaves unstyled on purpose: boulder-photo is what the Server's focus
    // lightbulb (boulder-focus.css, Server interop) dims around, and the client has no focus mode.
    private static readonly HashSet<string> Unstyled =
    [
        "boulder-photo",
    ];

    private static readonly string Root = FeedBulkSiteScanner.RepoRoot();

    [Fact]
    public void TheShell_LoadsNoWebStylesheet()
    {
        Assert.All(OfflineClientShellAssets.Styles, label => Assert.True(
            label.StartsWith(OfflineClientShellAssets.ClientPrefix, StringComparison.Ordinal) || label.StartsWith("_content/Blocwerk.Shared.Ui/", StringComparison.Ordinal),
            $"{label} is a Web stylesheet: every Server CSS edit would be a new client version"));
        Assert.DoesNotContain(OfflineClientShellAssets.All, label => label.StartsWith("css/", StringComparison.Ordinal));
    }

    [Fact]
    public async Task EveryClassTheViewsRender_IsStyledByTheClientsStylesheets()
    {
        var css = string.Concat(OfflineClientShellAssets.Styles.Select(label => File.ReadAllText(Source(label))));
        var styled = CssClass().Matches(css).Select(m => m.Groups[1].Value).ToHashSet(StringComparer.Ordinal);

        var rendered = new HashSet<string>(StringComparer.Ordinal);
        foreach (var html in await RenderAllAsync())
        {
            foreach (Match attribute in ClassAttribute().Matches(html))
            {
                rendered.UnionWith(attribute.Groups[1].Value.Split(' ', StringSplitOptions.RemoveEmptyEntries));
            }
        }

        Assert.True(rendered.Count > 60, $"only {rendered.Count} classes rendered");
        Assert.Empty(rendered.Where(c => !styled.Contains(c) && !Unstyled.Contains(c)).Order());
    }

    private static async Task<List<string>> RenderAllAsync()
    {
        await using var view = await ViewHarness.StartAsync(CachedDevice(UserA), $"walls/{Wall}");
        var pages = new List<string>
        {
            await view.RenderAsync<WallListPage>([]),
            await view.RenderAsync<WallViewPage>(new() { ["WallId"] = Wall }),
            await view.RenderAsync<Blocwerk.Client.Views.BoulderFilters>(new() { ["Filter"] = new Blocwerk.Client.Views.BoulderFilter(), ["ShowMine"] = true, ["StartOpen"] = true }),
        };
        foreach (var boulder in new[] { Crimp, Slab, Draft })
        {
            pages.Add(await view.RenderAsync<BoulderPage>(new() { ["WallId"] = Wall, ["BoulderId"] = boulder }));
        }

        return pages;
    }

    private static string Source(string label) => label.StartsWith("v/", StringComparison.Ordinal)
        ? Path.Combine(Root, "src", "Blocwerk.Client", "wwwroot", label[2..])
        : Path.Combine(Root, "src", "Blocwerk.Shared.Ui", "wwwroot", label["_content/Blocwerk.Shared.Ui/".Length..]);

    [GeneratedRegex("\\.(-?[a-zA-Z_][a-zA-Z0-9_-]*)")]
    private static partial Regex CssClass();

    [GeneratedRegex("class=\"([^\"]*)\"")]
    private static partial Regex ClassAttribute();
}
